.skh-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #fff);z-index:5;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #000);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.skh-root,.skh-root *,.skh-root *::before,.skh-root *::after{box-sizing:border-box}
.skh-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.skh-root img{display:block;border:0;max-width:none}
.skh-root .n64_3927{background-color:var(--wa-bg, #fff);align-content:stretch;display:flex;height:29px;align-items:center;padding-top:3px;padding-bottom:3px;position:relative;border-radius:5px;flex-shrink:0;width:90px;filter:drop-shadow(1px 1px 0px rgba(6,1,7,0.21))}
.skh-root .n64_3928{align-content:stretch;display:flex;flex:1 0 0;flex-direction:column;height:100%;align-items:center;justify-content:center;min-width:1px;position:relative}
.skh-root .n64_3929{word-break:break-word;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:400;line-height:14px;font-style:normal;position:relative;flex-shrink:0;color:var(--wa-text-sub, #828ea4);font-size:12px;white-space:nowrap;width:14px}
.skh-root .n64_3930{align-content:stretch;display:flex;flex:1 0 0;height:100%;align-items:center;justify-content:center;min-width:1px;position:relative;background-image:linear-gradient(to right,var(--wa-surface, #dce1ea),color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 0%, transparent) 21.698%)}
.skh-root .n64_3931{word-break:break-word;font-family:"Tomorrow","Pretendard",system-ui,sans-serif;font-weight:400;line-height:16px;font-style:normal;position:relative;flex-shrink:0;font-size:13px;color:var(--wa-text, #000);white-space:nowrap;width:17px}
.skh-root .n64_3932{position:absolute;left:-5px;width:10px;height:10px;top:9.5px}
.skh-root .x108{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.skh-root[data-theme="dark"] .n64_3927{background-color:var(--wa-point, #171b2c);filter:drop-shadow(1px 1px 0px rgba(0,0,0,0.5))}
.skh-root[data-theme="dark"] .n64_3929{color:var(--wa-text-sub, #9aa5c0)}
.skh-root[data-theme="dark"] .n64_3930{background-image:linear-gradient(to right,var(--wa-surface, #39405c),color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 0%, transparent) 21.698%)}
.skh-root[data-theme="dark"] .n64_3931{color:var(--wa-text, #e9ecf6)}
.skh-root[data-theme="dark"] [id="skh-Needle"] svg [id$="-Vector"] path{fill:var(--wa-point, #242a44)}
.skh-root[data-theme="dark"] [id="skh-Needle"] svg [id$="-Vector_2"] path{fill:var(--wa-point, #dfe3f2)}
.skh-root[data-theme="dark"] [id="skh-Needle"] svg [id$="-Vector_3"]{stroke:var(--wa-point, #dfe3f2)}
.skh-root[data-theme="dark"] [id="skh-Needle"] img{filter:invert(.86) hue-rotate(180deg)}
.skh-root[data-theme="dark"] [id="skh-Radio"] svg rect:first-of-type{fill:var(--wa-point, #2a3050)}
